ALTER TABLE "ai_tool_configs" ADD COLUMN IF NOT EXISTS "payload" jsonb;
UPDATE "ai_tool_configs" SET "title"='Tạo Ảnh Chân Dung Cinematic 8K Học Viên & Doanh Nhân Việt' WHERE "item_key"='prompt-01';
UPDATE "ai_tool_configs" SET "title"='Chuyên Gia Copywriting Viết Bài Sales Page Chuyển Đổi Cao' WHERE "item_key"='prompt-02';
UPDATE "ai_tool_configs" SET "title"='Kỹ Sư AI Tự Động Viết & Tối Ưu Code Python Enterprise' WHERE "item_key"='prompt-03';
UPDATE "ai_tool_configs" SET "title"='Thiết Kế Logo Vector Minimalist Thương Hiệu Sang Trọng' WHERE "item_key"='prompt-04';
UPDATE "ai_tool_configs" SET "title"='Lập Kế Hoạch Chiến Lược Content Marketing 30 Ngày' WHERE "item_key"='prompt-05';
UPDATE "ai_tool_configs" SET "title"='Phân Tích & Tóm Tắt Báo Cáo Tài Chính / Tài Liệu PDF Dài' WHERE "item_key"='prompt-06';
UPDATE "ai_tool_configs" SET "title"='Tạo Phối Cảnh Nội Thất Căn Hộ Luxury Modern 3D' WHERE "item_key"='prompt-07';
UPDATE "ai_tool_configs" SET "title"='Kịch Bản Chatbot AI Tư Vấn & Chăm Sóc Khách Hàng Tự Động' WHERE "item_key"='prompt-08';

UPDATE "ai_tool_configs" SET "title"='Tạo Ảnh Chân Dùng Cinematic 8K Học Viên & Doanh Nhân Việt', "is_paid"=true, "payload"='{"category":"Photography","model":"Midjourney v6","modelBadgeColor":"bg-purple-500/10 text-purple-600 border-purple-200","authorName":"MinhTu_AIArt","authorAvatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80","authorBadge":"Top Creator","rating":4.9,"reviewsCount":142,"salesCount":890,"image":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80","description":"Bộ prompt tạo ảnh chân dung góc rộng cinematic sắc nét dành riêng cho khuôn mặt và phong cách người Việt Nam. Phù hợp làm banner, avatar chuyên nghiệp.","template":"A high resolution cinematic 8k photograph of [subject], standing confidently in a modern [setting], [lighting], shallow depth of field, [color_grade], shot on 35mm lens --ar 16:9 --style raw --v 6.0","variables":[{"name":"subject","label":"Đối Tượng","defaultValue":"28-year-old Vietnamese female AI researcher smiling","placeholder":"Ví dụ: 30-year-old Vietnamese male tech manager"},{"name":"setting","label":"Không Gian","defaultValue":"high-tech AI academy office with glass windows","placeholder":"Ví dụ: modern workspace in Hanoi"},{"name":"lighting","label":"Ánh Sáng","defaultValue":"warm professional studio lighting","placeholder":"Ví dụ: cinematic evening golden hour"},{"name":"color_grade","label":"Tông Màu","defaultValue":"teal and orange color grade","placeholder":"Ví dụ: neutral minimalist tones"}],"instructions":"Nhập các tham số đối tượng và không gian vào vị trí [subject] và [setting]. Bạn có thể thay đổi tỉ lệ --ar 16:9 thành --ar 1:1 cho avatar vuông.","sampleOutputs":["https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=800&q=80"],"tags":["Midjourney","Portrait","Vietnamese","Photorealistic","Cinematic"],"isFeatured":true}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-01';
UPDATE "ai_tool_configs" SET "title"='Chuyên Gia Copywriting Viết Bài Sales Page Chuyển Đổi Cao', "is_paid"=false, "payload"='{"category":"Marketing","model":"ChatGPT 4o","modelBadgeColor":"bg-emerald-500/10 text-emerald-600 border-emerald-200","authorName":"GATS_Academy","authorAvatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","authorBadge":"Official","rating":5,"reviewsCount":310,"salesCount":2450,"image":"https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=800&q=80","description":"Khung prompt chuẩn hóa công thức AIDA & PAS, giúp viết trang bán hàng và bài quảng cáo Facebook thu hút khách hàng tiềm năng tức thì.","template":"Bạn là một Chuyên gia Copywriter thương mại điện tử. Hãy viết bài viết quảng cáo bán hàng cho [product_name] nhắm tới nhóm khách hàng [target_audience]. Mục tiêu chính là [conversion_goal]. Sử dụng giọng văn [tone_style] và chèn 3 lời kêu gọi hành động (CTA) cực mạnh.","variables":[{"name":"product_name","label":"Tên Sản Phẩm","defaultValue":"Khóa học AI Workflow Thực Chiến","placeholder":"Tên sản phẩm/dịch vụ của bạn"},{"name":"target_audience","label":"Khách Hàng Mục Tiêu","defaultValue":"Chủ doanh nghiệp nhỏ và Chuyên viên Marketing","placeholder":"Ví dụ: Nhân viên văn phòng, Học sinh"},{"name":"conversion_goal","label":"Mục Tiêu Chuyển Đổi","defaultValue":"Đăng ký tư vấn miễn phí ngay hôm nay","placeholder":"Mua hàng, Đăng ký dùng thử..."},{"name":"tone_style","label":"Phong Cách","defaultValue":"Thuyết phục, uy tín và năng lượng tích cực","placeholder":"Ví dụ: Thân thiện, Chuyên nghiệp"}],"instructions":"Điền thông tin chi tiết vào các ô biến bên dưới. Bạn có thể yêu cầu AI xuất ra định dạng Markdown hoặc HTML sẵn sàng đăng bài.","sampleOutputs":["https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=800&q=80"],"tags":["ChatGPT","Marketing","Copywriting","SalesPage","AIDA"],"isFeatured":true}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-02';
UPDATE "ai_tool_configs" SET "title"='Kỹ Sư AI Tự Động Viết & Tối Ưu Code Python Enterprise', "is_paid"=true, "payload"='{"category":"Coding","model":"DeepSeek R1","modelBadgeColor":"bg-blue-500/10 text-blue-600 border-blue-200","authorName":"DevMaster_VN","authorAvatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80","rating":4.8,"reviewsCount":98,"salesCount":520,"image":"https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80","description":"Prompts lập luận suy luận sâu (Chain-of-Thought) cho DeepSeek R1 để tạo mã nguồn Python chuẩn PEP8, đầy đủ Type Hinting & Unit Test.","template":"System Prompt: You are a Principal Software Architect.\nTask: Design and implement a production-ready [module_name] in Python using [framework].\nRequirements:\n1. Use clean architecture & solid design patterns.\n2. Handle [edge_case] with proper exceptions.\n3. Include comprehensive pytest unit tests for primary workflow.","variables":[{"name":"module_name","label":"Tên Module","defaultValue":"Async Web Scraper & Data Pipeline","placeholder":"Tên module hoặc tính năng"},{"name":"framework","label":"Framework/Thư viện","defaultValue":"FastAPI, Pydantic & Asyncio","placeholder":"Ví dụ: Django, Flask, Pandas"},{"name":"edge_case","label":"Trường Hợp Ngoại Lệ","defaultValue":"rate limiting & connection timeout gracefully","placeholder":"Ví dụ: invalid token format"}],"instructions":"Sử dụng với DeepSeek R1 hoặc Claude 3.5 Sonnet. Yêu cầu mô hình hiển thị từng bước suy luận (Chain of Thought) trước khi viết code.","sampleOutputs":["https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80"],"tags":["DeepSeek","Python","Coding","Backend","FastAPI"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-03';
UPDATE "ai_tool_configs" SET "title"='Thiết Kế Logo Vector Minimalist Thương Hiệu Sang Trọng', "is_paid"=true, "payload"='{"category":"Design","model":"Flux.1 AI","modelBadgeColor":"bg-amber-500/10 text-amber-600 border-amber-200","authorName":"StudioDesign_Pro","authorAvatar":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=200&q=80","rating":4.9,"reviewsCount":76,"salesCount":430,"image":"https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80","description":"Bộ prompt thiết kế logo phong cách tối giản phẳng, vector sắc nét không dính chữ, thích hợp làm nhận diện thương hiệu cho Startup.","template":"A modern minimalist flat vector logo for a brand named [brand_name], featuring a sleek [icon_symbol], geometric shapes, solid background, primary color [color_scheme], professional branding asset --no text, photorealism, noise","variables":[{"name":"brand_name","label":"Tên Thương Hiệu","defaultValue":"EduGats AI Academy","placeholder":"Tên công ty/thương hiệu"},{"name":"icon_symbol","label":"Biểu Tượng","defaultValue":"tech brain node with glowing orange spark","placeholder":"Ví dụ: lotus flower, lion crest"},{"name":"color_scheme","label":"Tông Màu","defaultValue":"deep orange and dark navy blue","placeholder":"Ví dụ: luxury gold and black"}],"instructions":"Sử dụng tốt nhất với Flux.1 Dev hoặc DALL-E 3. Đảm bảo sử dụng tham số --no text nếu không muốn logo có chữ thừa.","sampleOutputs":["https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80"],"tags":["Flux","Logo","Vector","Design","Minimalist"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-04';
UPDATE "ai_tool_configs" SET "title"='Lập Kế Hoạch Chiến Lược Content Marketing 30 Ngày', "is_paid"=true, "payload"='{"category":"Business","model":"ChatGPT 4o","modelBadgeColor":"bg-emerald-500/10 text-emerald-600 border-emerald-200","authorName":"StrategyGuru","authorAvatar":"https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?auto=format&fit=crop&w=200&q=80","rating":5,"reviewsCount":189,"salesCount":1120,"image":"https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80","description":"Xây dựng ma trận nội dung 30 ngày tự động hóa cho Fanpage/LinkedIn, chia theo 4 cột trụ: Giáo dục, Niềm tin, Tương tác và Chuyển đổi.","template":"Lập một lịch trình Kế hoạch Nội dung 30 ngày cho thương hiệu [brand_topic] phát triển trên nền tảng [platform_name]. Cấu trúc bảng gồm 5 cột: Ngày, Cột trụ nội dung, Tiêu đề bài viết, Tóm tắt ý chính và Lời kêu gọi hành động (CTA). Mục tiêu chính: [business_goal].","variables":[{"name":"brand_topic","label":"Chủ Đề Thương Hiệu","defaultValue":"Đào tạo kỹ năng AI cho nhân sự doanh nghiệp","placeholder":"Lĩnh vực kinh doanh"},{"name":"platform_name","label":"Nền Tảng","defaultValue":"Facebook Fanpage & LinkedIn","placeholder":"TikTok, Youtube, Website..."},{"name":"business_goal","label":"Mục Tiêu Doanh Nghiệp","defaultValue":"Tăng lượng đăng ký khóa học thử nghiệm 20%","placeholder":"Tăng follow, kéo traffic..."}],"instructions":"Sao chép bảng kết quả từ ChatGPT trực tiếp vào Google Sheets hoặc Excel để phân công cho đội ngũ Content.","sampleOutputs":["https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80"],"tags":["ChatGPT","ContentPlan","Business","Marketing","Strategy"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-05';
UPDATE "ai_tool_configs" SET "title"='Phân Tích & Tóm Tắt Báo Cáo Tài Chính / Tài Liệu PDF Dài', "is_paid"=false, "payload"='{"category":"Productivity","model":"Claude 3.5 Sonnet","modelBadgeColor":"bg-amber-500/10 text-amber-600 border-amber-200","authorName":"GATS_Academy","authorAvatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","authorBadge":"Official","rating":4.9,"reviewsCount":215,"salesCount":1890,"image":"https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=800&q=80","description":"Trích xuất nhanh các chỉ số cốt lõi, ma trận rủi ro và bản tóm tắt điều hành Executive Summary từ tài liệu hàng trăm trang.","template":"Bạn là một Chuyên gia Phân tích Tài chính & Dữ liệu. Hãy đọc tài liệu đính kèm về [document_name] và trích xuất:\n1. Tóm tắt điều hành 3 câu ngắn gọn.\n2. Bảng 5 chỉ số tài chính quan trọng nhất.\n3. Phân tích 3 rủi ro chính và đề xuất giải pháp kiểm soát.","variables":[{"name":"document_name","label":"Tên Tài Liệu","defaultValue":"Báo cáo tài chính quý 4 năm 2025","placeholder":"Tên tài liệu hoặc đề án"}],"instructions":"Đính kèm file PDF hoặc dán văn bản trực tiếp vào cửa sổ chat cùng với prompt này trên Claude 3.5 Sonnet.","sampleOutputs":["https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=800&q=80"],"tags":["Claude","Productivity","Finance","PDF","Analysis"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-06';
UPDATE "ai_tool_configs" SET "title"='Tạo Phối Cảnh Nội Thất Căn Hộ Luxury Modern 3D', "is_paid"=true, "payload"='{"category":"Art & 3D","model":"Midjourney v6","modelBadgeColor":"bg-purple-500/10 text-purple-600 border-purple-200","authorName":"ArchViz_Pro","authorAvatar":"https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80","rating":4.9,"reviewsCount":62,"salesCount":380,"image":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80","description":"Prompt dựng phối cảnh 3D nội thất kiến trúc sang trọng, chi tiết mảng tường gỗ, đá marble và ánh sáng tự nhiên.","template":"3D interior rendering of a luxury [room_type], Scandinavian minimalist style, [materials], floor to ceiling windows, natural afternoon light, octane render, 8k resolution --ar 16:9 --v 6.0","variables":[{"name":"room_type","label":"Loại Phòng","defaultValue":"living room penthouse","placeholder":"Ví dụ: bedroom, kitchen, office"},{"name":"materials","label":"Vật Liệu Khung","defaultValue":"natural oak wood paneling, marble coffee table, beige velvet sofa","placeholder":"Mô tả chất liệu đồ nội thất"}],"instructions":"Sử dụng tham số --ar 16:9 cho ảnh ngang hoặc --ar 4:3 cho góc nhìn cận cảnh.","sampleOutputs":["https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80"],"tags":["Midjourney","Architecture","3D","Interior","Luxury"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-07';
UPDATE "ai_tool_configs" SET "title"='Kịch Bản Chatbot AI Tư Vấn & Chăm Sóc Khách Hàng Tự Động', "is_paid"=true, "payload"='{"category":"AI Agents","model":"ChatGPT 4o","modelBadgeColor":"bg-emerald-500/10 text-emerald-600 border-emerald-200","authorName":"AIAgent_Factory","authorAvatar":"https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=200&q=80","authorBadge":"Verified","rating":5,"reviewsCount":145,"salesCount":970,"image":"https://images.unsplash.com/photo-1531403009284-440f080d1e12?auto=format&fit=crop&w=800&q=80","description":"Prompt đóng vai AI Agent tư vấn bán hàng chuyên nghiệp, xử lý từ chối giá khéo léo và điều hướng chốt đơn.","template":"Bạn là Chuyên viên tư vấn AI đại diện cho [company_name]. Nhiệm vụ chính là giải đáp thắc mắc về dịch vụ [service_description]. Khi khách hàng băn khoăn về giá cả, hãy nhấn mạnh chính sách [policy_highlight] và đưa ra câu hỏi đóng để chốt cuộc hẹn.","variables":[{"name":"company_name","label":"Tên Công Ty","defaultValue":"GATS Academy","placeholder":"Tên đơn vị của bạn"},{"name":"service_description","label":"Mô Tả Dịch Vụ","defaultValue":"Khóa học AI Automation cho Doanh nghiệp","placeholder":"Sản phẩm/dịch vụ chính"},{"name":"policy_highlight","label":"Điểm Nổi Bật","defaultValue":"Cam kết hoàn tiền trong 7 ngày & hỗ trợ 1-1","placeholder":"Ưu đãi độc quyền"}],"instructions":"Dán prompt này vào System Prompt của OpenAI Assistants API, Dify hoặc Flowise.","sampleOutputs":["https://images.unsplash.com/photo-1531403009284-440f080d1e12?auto=format&fit=crop&w=800&q=80"],"tags":["ChatGPT","AIAgents","Chatbot","CustomerService","Automation"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-08';

UPDATE "ai_tool_configs" SET "payload"='{"category":"Photography","model":"Midjourney v6","modelBadgeColor":"bg-purple-500/10 text-purple-600 border-purple-200","price":"$2.99","authorName":"MinhTu_AIArt","authorAvatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=200&q=80","authorBadge":"Top Creator","rating":4.9,"reviewsCount":142,"salesCount":890,"image":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80","description":"Bộ prompt tạo ảnh chân dung góc rộng cinematic sắc nét dành riêng cho khuôn mặt và phong cách người Việt Nam. Phù hợp làm banner, avatar chuyên nghiệp.","template":"A high resolution cinematic 8k photograph of [subject], standing confidently in a modern [setting], [lighting], shallow depth of field, [color_grade], shot on 35mm lens --ar 16:9 --style raw --v 6.0","variables":[{"name":"subject","label":"Đối Tượng","defaultValue":"28-year-old Vietnamese female AI researcher smiling","placeholder":"Ví dụ: 30-year-old Vietnamese male tech manager"},{"name":"setting","label":"Không Gian","defaultValue":"high-tech AI academy office with glass windows","placeholder":"Ví dụ: modern workspace in Hanoi"},{"name":"lighting","label":"Ánh Sáng","defaultValue":"warm professional studio lighting","placeholder":"Ví dụ: cinematic evening golden hour"},{"name":"color_grade","label":"Tông Màu","defaultValue":"teal and orange color grade","placeholder":"Ví dụ: neutral minimalist tones"}],"instructions":"Nhập các tham số đối tượng và không gian vào vị trí [subject] và [setting]. Bạn có thể thay đổi tỉ lệ --ar 16:9 thành --ar 1:1 cho avatar vuông.","sampleOutputs":["https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80","https://images.unsplash.com/photo-1560250097-0b93528c311a?auto=format&fit=crop&w=800&q=80"],"tags":["Midjourney","Portrait","Vietnamese","Photorealistic","Cinematic"],"isFeatured":true}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-01';
UPDATE "ai_tool_configs" SET "payload"='{"category":"Marketing","model":"ChatGPT 4o","modelBadgeColor":"bg-emerald-500/10 text-emerald-600 border-emerald-200","price":"Miễn phí","authorName":"GATS_Academy","authorAvatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","authorBadge":"Official","rating":5,"reviewsCount":310,"salesCount":2450,"image":"https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=800&q=80","description":"Khung prompt chuẩn hóa công thức AIDA & PAS, giúp viết trang bán hàng và bài quảng cáo Facebook thu hút khách hàng tiềm năng tức thì.","template":"Bạn là một Chuyên gia Copywriter thương mại điện tử. Hãy viết bài viết quảng cáo bán hàng cho [product_name] nhắm tới nhóm khách hàng [target_audience]. Mục tiêu chính là [conversion_goal]. Sử dụng giọng văn [tone_style] và chèn 3 lời kêu gọi hành động (CTA) cực mạnh.","variables":[{"name":"product_name","label":"Tên Sản Phẩm","defaultValue":"Khóa học AI Workflow Thực Chiến","placeholder":"Tên sản phẩm/dịch vụ của bạn"},{"name":"target_audience","label":"Khách Hàng Mục Tiêu","defaultValue":"Chủ doanh nghiệp nhỏ và Chuyên viên Marketing","placeholder":"Ví dụ: Nhân viên văn phòng, Học sinh"},{"name":"conversion_goal","label":"Mục Tiêu Chuyển Đổi","defaultValue":"Đăng ký tư vấn miễn phí ngay hôm nay","placeholder":"Mua hàng, Đăng ký dùng thử..."},{"name":"tone_style","label":"Phong Cách","defaultValue":"Thuyết phục, uy tín và năng lượng tích cực","placeholder":"Ví dụ: Thân thiện, Chuyên nghiệp"}],"instructions":"Điền thông tin chi tiết vào các ô biến bên dưới. Bạn có thể yêu cầu AI xuất ra định dạng Markdown hoặc HTML sẵn sàng đăng bài.","sampleOutputs":["https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=800&q=80"],"tags":["ChatGPT","Marketing","Copywriting","SalesPage","AIDA"],"isFeatured":true}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-02';
UPDATE "ai_tool_configs" SET "payload"='{"category":"Coding","model":"DeepSeek R1","modelBadgeColor":"bg-blue-500/10 text-blue-600 border-blue-200","price":"$3.99","authorName":"DevMaster_VN","authorAvatar":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=200&q=80","rating":4.8,"reviewsCount":98,"salesCount":520,"image":"https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80","description":"Prompts lập luận suy luận sâu (Chain-of-Thought) cho DeepSeek R1 để tạo mã nguồn Python chuẩn PEP8, đầy đủ Type Hinting & Unit Test.","template":"System Prompt: You are a Principal Software Architect.\nTask: Design and implement a production-ready [module_name] in Python using [framework].\nRequirements:\n1. Use clean architecture & solid design patterns.\n2. Handle [edge_case] with proper exceptions.\n3. Include comprehensive pytest unit tests for primary workflow.","variables":[{"name":"module_name","label":"Tên Module","defaultValue":"Async Web Scraper & Data Pipeline","placeholder":"Tên module hoặc tính năng"},{"name":"framework","label":"Framework/Thư viện","defaultValue":"FastAPI, Pydantic & Asyncio","placeholder":"Ví dụ: Django, Flask, Pandas"},{"name":"edge_case","label":"Trường Hợp Ngoại Lệ","defaultValue":"rate limiting & connection timeout gracefully","placeholder":"Ví dụ: invalid token format"}],"instructions":"Sử dụng với DeepSeek R1 hoặc Claude 3.5 Sonnet. Yêu cầu mô hình hiển thị từng bước suy luận (Chain of Thought) trước khi viết code.","sampleOutputs":["https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=800&q=80"],"tags":["DeepSeek","Python","Coding","Backend","FastAPI"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-03';
UPDATE "ai_tool_configs" SET "payload"='{"category":"Design","model":"Flux.1 AI","modelBadgeColor":"bg-amber-500/10 text-amber-600 border-amber-200","price":"$1.99","authorName":"StudioDesign_Pro","authorAvatar":"https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=200&q=80","rating":4.9,"reviewsCount":76,"salesCount":430,"image":"https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80","description":"Bộ prompt thiết kế logo phong cách tối giản phẳng, vector sắc nét không dính chữ, thích hợp làm nhận diện thương hiệu cho Startup.","template":"A modern minimalist flat vector logo for a brand named [brand_name], featuring a sleek [icon_symbol], geometric shapes, solid background, primary color [color_scheme], professional branding asset --no text, photorealism, noise","variables":[{"name":"brand_name","label":"Tên Thương Hiệu","defaultValue":"EduGats AI Academy","placeholder":"Tên công ty/thương hiệu"},{"name":"icon_symbol","label":"Biểu Tượng","defaultValue":"tech brain node with glowing orange spark","placeholder":"Ví dụ: lotus flower, lion crest"},{"name":"color_scheme","label":"Tông Màu","defaultValue":"deep orange and dark navy blue","placeholder":"Ví dụ: luxury gold and black"}],"instructions":"Sử dụng tốt nhất với Flux.1 Dev hoặc DALL-E 3. Đảm bảo sử dụng tham số --no text nếu không muốn logo có chữ thừa.","sampleOutputs":["https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80"],"tags":["Flux","Logo","Vector","Design","Minimalist"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-04';
UPDATE "ai_tool_configs" SET "payload"='{"category":"Business","model":"ChatGPT 4o","modelBadgeColor":"bg-emerald-500/10 text-emerald-600 border-emerald-200","price":"$4.99","authorName":"StrategyGuru","authorAvatar":"https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?auto=format&fit=crop&w=200&q=80","rating":5,"reviewsCount":189,"salesCount":1120,"image":"https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80","description":"Xây dựng ma trận nội dung 30 ngày tự động hóa cho Fanpage/LinkedIn, chia theo 4 cột trụ: Giáo dục, Niềm tin, Tương tác và Chuyển đổi.","template":"Lập một lịch trình Kế hoạch Nội dung 30 ngày cho thương hiệu [brand_topic] phát triển trên nền tảng [platform_name]. Cấu trúc bảng gồm 5 cột: Ngày, Cột trụ nội dung, Tiêu đề bài viết, Tóm tắt ý chính và Lời kêu gọi hành động (CTA). Mục tiêu chính: [business_goal].","variables":[{"name":"brand_topic","label":"Chủ Đề Thương Hiệu","defaultValue":"Đào tạo kỹ năng AI cho nhân sự doanh nghiệp","placeholder":"Lĩnh vực kinh doanh"},{"name":"platform_name","label":"Nền Tảng","defaultValue":"Facebook Fanpage & LinkedIn","placeholder":"TikTok, Youtube, Website..."},{"name":"business_goal","label":"Mục Tiêu Doanh Nghiệp","defaultValue":"Tăng lượng đăng ký khóa học thử nghiệm 20%","placeholder":"Tăng follow, kéo traffic..."}],"instructions":"Sao chép bảng kết quả từ ChatGPT trực tiếp vào Google Sheets hoặc Excel để phân công cho đội ngũ Content.","sampleOutputs":["https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80"],"tags":["ChatGPT","ContentPlan","Business","Marketing","Strategy"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-05';
UPDATE "ai_tool_configs" SET "payload"='{"category":"Productivity","model":"Claude 3.5 Sonnet","modelBadgeColor":"bg-amber-500/10 text-amber-600 border-amber-200","price":"Miễn phí","authorName":"GATS_Academy","authorAvatar":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=200&q=80","authorBadge":"Official","rating":4.9,"reviewsCount":215,"salesCount":1890,"image":"https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=800&q=80","description":"Trích xuất nhanh các chỉ số cốt lõi, ma trận rủi ro và bản tóm tắt điều hành Executive Summary từ tài liệu hàng trăm trang.","template":"Bạn là một Chuyên gia Phân tích Tài chính & Dữ liệu. Hãy đọc tài liệu đính kèm về [document_name] và trích xuất:\n1. Tóm tắt điều hành 3 câu ngắn gọn.\n2. Bảng 5 chỉ số tài chính quan trọng nhất.\n3. Phân tích 3 rủi ro chính và đề xuất giải pháp kiểm soát.","variables":[{"name":"document_name","label":"Tên Tài Liệu","defaultValue":"Báo cáo tài chính quý 4 năm 2025","placeholder":"Tên tài liệu hoặc đề án"}],"instructions":"Đính kèm file PDF hoặc dán văn bản trực tiếp vào cửa sổ chat cùng với prompt này trên Claude 3.5 Sonnet.","sampleOutputs":["https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=800&q=80"],"tags":["Claude","Productivity","Finance","PDF","Analysis"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-06';
UPDATE "ai_tool_configs" SET "payload"='{"category":"Art & 3D","model":"Midjourney v6","modelBadgeColor":"bg-purple-500/10 text-purple-600 border-purple-200","price":"$3.49","authorName":"ArchViz_Pro","authorAvatar":"https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=200&q=80","rating":4.9,"reviewsCount":62,"salesCount":380,"image":"https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80","description":"Prompt dựng phối cảnh 3D nội thất kiến trúc sang trọng, chi tiết mảng tường gỗ, đá marble và ánh sáng tự nhiên.","template":"3D interior rendering of a luxury [room_type], Scandinavian minimalist style, [materials], floor to ceiling windows, natural afternoon light, octane render, 8k resolution --ar 16:9 --v 6.0","variables":[{"name":"room_type","label":"Loại Phòng","defaultValue":"living room penthouse","placeholder":"Ví dụ: bedroom, kitchen, office"},{"name":"materials","label":"Vật Liệu Khung","defaultValue":"natural oak wood paneling, marble coffee table, beige velvet sofa","placeholder":"Mô tả chất liệu đồ nội thất"}],"instructions":"Sử dụng tham số --ar 16:9 cho ảnh ngang hoặc --ar 4:3 cho góc nhìn cận cảnh.","sampleOutputs":["https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80"],"tags":["Midjourney","Architecture","3D","Interior","Luxury"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-07';
UPDATE "ai_tool_configs" SET "payload"='{"category":"AI Agents","model":"ChatGPT 4o","modelBadgeColor":"bg-emerald-500/10 text-emerald-600 border-emerald-200","price":"$5.99","authorName":"AIAgent_Factory","authorAvatar":"https://images.unsplash.com/photo-1570295999919-56ceb5ecca61?auto=format&fit=crop&w=200&q=80","authorBadge":"Verified","rating":5,"reviewsCount":145,"salesCount":970,"image":"https://images.unsplash.com/photo-1531403009284-440f080d1e12?auto=format&fit=crop&w=800&q=80","description":"Prompt đóng vai AI Agent tư vấn bán hàng chuyên nghiệp, xử lý từ chối giá khéo léo và điều hướng chốt đơn.","template":"Bạn là Chuyên viên tư vấn AI đại diện cho [company_name]. Nhiệm vụ chính là giải đáp thắc mắc về dịch vụ [service_description]. Khi khách hàng băn khoăn về giá cả, hãy nhấn mạnh chính sách [policy_highlight] và đưa ra câu hỏi đóng để chốt cuộc hẹn.","variables":[{"name":"company_name","label":"Tên Công Ty","defaultValue":"GATS Academy","placeholder":"Tên đơn vị của bạn"},{"name":"service_description","label":"Mô Tả Dịch Vụ","defaultValue":"Khóa học AI Automation cho Doanh nghiệp","placeholder":"Sản phẩm/dịch vụ chính"},{"name":"policy_highlight","label":"Điểm Nổi Bật","defaultValue":"Cam kết hoàn tiền trong 7 ngày & hỗ trợ 1-1","placeholder":"Ưu đãi độc quyền"}],"instructions":"Dán prompt này vào System Prompt của OpenAI Assistants API, Dify hoặc Flowise.","sampleOutputs":["https://images.unsplash.com/photo-1531403009284-440f080d1e12?auto=format&fit=crop&w=800&q=80"],"tags":["ChatGPT","AIAgents","Chatbot","CustomerService","Automation"]}'::jsonb WHERE "type"='prompt' AND "item_key"='prompt-08';
